function expandQueryTerms(query, language) {
  const q = query.toLowerCase();
  const terms = new Set();
  // Only add the query's own raw words when it's German: they're then
  // genuine German legal terms worth substring-matching directly. For an
  // English query, a raw word like "and" or "does" would otherwise
  // spuriously substring-match unrelated German words (e.g. "and" inside
  // "andere"/"anderen"/"Gegenstand"), swamping the real signal from the
  // glossary below with noise.
  if (language === "de") {
    for (const w of q.match(/[a-zäöüß]+/g) || []) terms.add(w);
  }
  for (const [phrase, deTerms] of Object.entries(GLOSSARY)) {
    if (q.includes(phrase)) for (const t of deTerms) terms.add(t);
  }
  return terms;
}

// Caps how many times any single term can count towards a section's
// score. Without this, a broad glossary term like "employer" -> "arbeitgeber"
// (ubiquitous in legal text) can rack up a huge raw count and drown out a
// rarer, far more diagnostic term like "löschung" that only appears a
// handful of times but pinpoints the actually relevant section.
const MAX_TERM_CONTRIBUTION = 4;

function lexicalSearch(query, language, topK = 5) {
  const terms = [...expandQueryTerms(query, language)].filter((t) => t.length > 2);
  if (!terms.length) return [];
  const scored = [];
  for (const s of ALL_SECTIONS) {
    const haystack = `${s.title_de} ${s.text_de}`.toLowerCase();
    let score = 0;
    for (const t of terms) {
      const count = haystack.split(t).length - 1;
      score += Math.min(count, MAX_TERM_CONTRIBUTION);
    }
    if (score > 0) scored.push([score, s]);
  }
  scored.sort((a, b) => b[0] - a[0]);
  return scored.slice(0, topK).map(([, s]) => s);
}

// ---------------------------------------------------------------------
// i18n (app/i18n.py)
// ---------------------------------------------------------------------
const GERMAN_CHARS = new Set([..."äöüßÄÖÜ"]);
const GERMAN_QUESTION_PREFIXES = [
  "wie ", "was ", "warum ", "wann ", "wo ", "wer ", "welche ", "welches ",
  "kann ", "muss ", "darf ", "ist ", "sind ", "wird ", "werden ",
  "dürfen ", "können ", "müssen ", "ohne ", "wenn ", "nicht ",
];
const ENGLISH_QUESTION_PREFIXES = [
  "what ", "why ", "when ", "where ", "who ", "which ", "how ",
  "can ", "must ", "may ", "is ", "are ", "will ", "does ", "do ",
  "should ", "could ", "would ", "without ", "if ", "not ",
];
const GERMAN_STOPWORDS = new Set([
  "der", "die", "das", "und", "ist", "wie", "kann", "muss", "darf",
  "wird", "werden", "eine", "einen", "einem", "einer", "nicht", "auf",
  "mit", "für", "von", "bei", "ohne", "wenn", "was", "wer", "wo",
  "warum", "wieso", "arbeitgeber", "arbeitnehmer", "betriebsrat",
  "kündigung", "gehalt", "urlaub", "dürfen", "können", "müssen",
]);
const ENGLISH_STOPWORDS = new Set([
  "the", "is", "can", "does", "do", "must", "may", "will", "a", "an",
  "not", "on", "with", "for", "from", "at", "without", "if", "what",
  "who", "where", "why", "employer", "employee", "works", "council",
  "termination", "salary", "vacation", "how", "which", "when",
]);

function detectLanguage(text) {
  if (!text || !text.trim()) return "en";
  const lowered = text.toLowerCase();
  const hasGermanChars = [...text].some((ch) => GERMAN_CHARS.has(ch));
  const hasEnglishPrefix = ENGLISH_QUESTION_PREFIXES.some((p) => lowered.startsWith(p));
  const hasGermanPrefix = GERMAN_QUESTION_PREFIXES.some((p) => lowered.startsWith(p));

  if (hasEnglishPrefix && !hasGermanPrefix) return "en";
  if (hasGermanPrefix && !hasEnglishPrefix) return "de";
  if (hasGermanChars && !hasEnglishPrefix) return "de";

  const words = new Set(lowered.match(/[a-zA-Z]+/g) || []);
  let deScore = 0;
  let enScore = 0;
  for (const w of words) {
    if (GERMAN_STOPWORDS.has(w)) deScore++;
    if (ENGLISH_STOPWORDS.has(w)) enScore++;
  }
  if (deScore === enScore) return "en";
  return deScore > enScore ? "de" : "en";
}

